// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract Vault {
    IERC20 public asset;
    uint256 public totalShares;
    mapping(address => uint256) public balanceOf;

    uint256 private constant INITIAL_SCALE = 1e18;

    constructor(address _asset) {
        asset = IERC20(_asset);
    }

    function totalAssets() public view returns (uint256) {
        return asset.balanceOf(address(this));
    }

    function deposit(uint256 assets) external returns (uint256 shares) {
        asset.transferFrom(msg.sender, address(this), assets);

        uint256 _totalAssets = totalAssets();
        uint256 _totalShares = totalShares;

        if (_totalShares == 0) {
            shares = assets * INITIAL_SCALE;
        } else {
            uint256 assetsBefore = _totalAssets - assets;
            shares = (assets * _totalShares) / assetsBefore;
        }

        totalShares += shares;
        balanceOf[msg.sender] += shares;
    }

    function redeem(uint256 shares) external returns (uint256 assets) {
        require(balanceOf[msg.sender] >= shares);

        uint256 _totalAssets = totalAssets();
        uint256 _totalShares = totalShares;

        assets = (shares * _totalAssets) / _totalShares;

        balanceOf[msg.sender] -= shares;
        totalShares -= shares;

        asset.transfer(msg.sender, assets);
    }
}
